export const TERMS: Term[] = [
  { term: "ECD", desc: "Equivalent Circulating Density: effective mud pressure while circulating, in ppg." },
  { term: "Measured ECD", desc: "ECD from the downhole PWD/APWD sensor (Rec 02).", keywords: "pwd apwd sensor" },
  { term: "ECD ⓥ (virtual)", desc: "Model-predicted ECD from surface parameters, used when there is no PWD sensor. Always shown with an interval.", keywords: "prediction virtual nowcast" },
  { term: "MW", desc: "Mud weight (Rec 04). ECD ⓥ = MW + hydraulic component, so MW is required.", keywords: "mud weight rec 04" },
  { term: "PWD sensor offset", desc: "Distance of the PWD/ECD sensor behind the bit (motor ±30 ft + MWD), default 40 ft, band 40–45 ft. Can be set per section from the tally. The hole below the sensor (and plugging at the bit/stabilizer) is not seen by measured ECD.", keywords: "offset sensor pwd blind spot behind bit tally motor mwd 40 ft" },
  { term: "ECD below sensor (pack-off)", desc: "Red line on the ECD track shown only while the pack-off detector is active: reference ECD + 0.2 × SPP rise / (0.052 × bit TVD). Dashed line = upper bound if fully plugged. The 0.2 factor is provisional (from GW339 without losses).", keywords: "pack off packoff ecd potential plug spp spike blind spot" },
  { term: "Calibration to last PWD", desc: "When PWD drops out, ECD ⓥ is shifted by the last measured ECD − model difference, which then decays (≈ one third after 6 h). Reset when the hole size changes. The ECD card shows 'calibrated to PWD ±x (n h ago)'.", keywords: "calibration offset pwd lost calibrated" },
  { term: "Well role", desc: "shadow = active well being monitored (not used for training); train = used for training; blind = fixed test well; case = case study.", keywords: "role shadow train blind case" },
  { term: "Well type", desc: "Horizontal (max inclination ≥ 80°), J (build-hold), S (drop-off ≥ 15° from max), Vertical (< 10°), computed from the Rec 07 survey. A well still being drilled is judged on the survey so far.", keywords: "well type j s horizontal vertical room group survey inclination" },
  { term: "PPFG", desc: "Pore pressure & fracture gradient (Rec 03 or manual input per MD interval): PP, SFG, FG min/max. Only the approved version is used.", keywords: "pp sfg fg rec 03" },
  { term: "Upper / lower margin", desc: "Upper margin = FG_min − ECD (at the bit and the weakest open-hole point). Lower margin = ECD − max(PP, SFG)." },
  { term: "Alert level", desc: "NORMAL, ADVISORY, WARNING, CRITICAL, UNAVAILABLE (cannot be computed). INFO is used for operational events." },
  { term: "LOWO", desc: "Leave-one-well-out: cross-validation holding out one train well at a time. Used to pick the model.", keywords: "cross validation" },
  { term: "Blind well", desc: "Fixed test well never used for training. Its accuracy is the most honest test." },
  { term: "MAE", desc: "Mean absolute error: average absolute difference between prediction and measurement (ppg). Lower is better.", keywords: "accuracy error" },
  { term: "MW-only baseline", desc: "The simplest reference model (ECD from MW alone). The ML model must beat it." },
  { term: "OOD", desc: "Out-of-distribution: input conditions outside the training data range → less reliable results (low confidence badge)." },
  { term: "DLS (dogleg severity)", desc: "Hole curvature per 100 ft (°/100 ft), computed from Rec 07 survey inclination & azimuth (minimum curvature). Basis of the bending and side-force estimates.", keywords: "dogleg curvature bend survey rec 07 sdls" },
  { term: "Bending moment (estimate)", desc: "Bending moment of the pipe/BHA following the hole curvature: M = E × I × curvature (kft·lbf). Ours is computed from the survey + string OD/ID (tools/bending script), unlike SLB's BND_MAX_DMM measured by a downhole sensor.", keywords: "bending pipe bnd dmm slb madpass" },
  { term: "Connection bending limit", desc: "Maximum safe curvature for a casing/pipe connection, from the manufacturer datasheet (°/100 ft or ksi). The bending script computes utilisation = bending ÷ limit (1.0 = at the limit) and flags depths ≥80% / over the limit. Casing is stiffer than DP, so its moment is much larger at the same DLS.", keywords: "connection casing liner limit utilisation datasheet" },
  { term: "Side force", desc: "Force of the pipe against the hole wall per joint (klbf), from tension × curvature + pipe weight. Tension is computed from string weight and calibrated to measured hookload. Closer to stuck risk (key-seat, differential) than bending alone.", keywords: "side force normal force wall key seat stuck" },
  { term: "Friction factor (FF) / broomstick", desc: "String–wall friction coefficient for the pick-up / slack-off hookload model. Model hookload curves vs depth are called a broomstick. Measured hookload above the pick-up curve = overpull, below the slack-off curve = drag/set-down.", keywords: "ff friction broomstick overpull drag hookload model torque drag" },
  { term: "Prediction interval", desc: "ECD ⓥ range from the LOWO error spread. Target: ±90% of measured ECD within the range." },
  { term: "Candidate / Shadow / Production", desc: "Model status: newly trained / running alongside for monitoring / official reference (needs 6/6 gates)." },
  { term: "Promotion gate", desc: "6 conditions before production: Data QC, Blind-well test, Engineering review, Shadow monitoring, Documented thresholds, Tested rollback." },
  { term: "Cut-off", desc: "Analysis mode where the engine only sees data up to time T, to test early signs before an event." },
  { term: "Lead time", desc: "Time between the first indication and the onset of a confirmed event." },
  { term: "Rathole", desc: "Open hole below the shoe not covered by casing (e.g. casing set early). Prone to sloughing." },
  { term: "Operating state", desc: "DRILL_ROT, SLIDE, REAM, WASH, CIRC, TRIP, STATIC; derived from flow, RPM, bit & block position." },
  { term: "Navita records", desc: "Rec 01 rig, 02 ECD (PWD), 03 PPFG, 04 mud weight, 07 survey, 08 LWD (optional)." },
  { term: "append / replace", desc: "Upload mode: append skips duplicate data (use for daily uploads; ranges may overlap); replace overwrites data at the same timestamps (correction files)." },
];

